// Version A: single function with case branches
function processPaymentA(payment: any) {
  switch (payment.type) {
    case 'card': return chargeCard(payment);
    case 'paypal': return chargePaypal(payment);
    default: throw new Error('unsupported');
  }
}

// Version B: registry of handlers
const processors: Record<string, (p: any) => any> = {
  card: (p) => chargeCard(p),
  paypal: (p) => chargePaypal(p),
};
function processPaymentB(payment: any) {
  const fn = processors[payment.type];
  if (!fn) throw new Error('unsupported');
  return fn(payment);
}
